class AsyncThreadMemberResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def remove(self, thread: str) -> None:
        """
        Remove a member from a thread
        Removes a user or agent from the explicit roster of a private or restricted
        thread. Team-visible threads use implicit membership and reject individual
        removals. A member may remove themself; removing someone else requires
        permission to modify the thread. A successful removal returns HTTP 204 with
        no response body.
        Supply either `user` or `agent` depending on the value of `type`. Returns 404
        if the thread or the membership record does not exist.

        Args:
            thread: Thread ID (`thr_...`) identifying the thread to remove the member from.

        Returns:
            Empty response body. HTTP 204 on success.
        """
        await self._http.request(f"/api/v1/threads/{thread}/members", method="DELETE")

    async def list(self, thread: str) -> ThreadMemberListResponse:
        """
        List members of a thread
        Returns all current user and agent members. Private and restricted threads
        return their explicit roster; team-visible threads return the owning team's
        implicit roster. The authenticated viewer must be able to see the thread.
        Results are returned as a flat array in the `data` field. The list is not
        paginated all members are returned in a single response.

        Args:
            thread: Thread ID (`thr_...`) identifying the thread to remove the member from.

        Returns:
            Successful response
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/members",
            response_type=ThreadMemberListResponse,
        )

    async def create(self, thread: str, input: ThreadMemberCreateInput) -> ChatMember:
        """
        Add a member to a thread
        Adds a user or agent to the explicit roster of a private or restricted
        thread. Team-visible threads use the owning team's implicit roster and reject
        explicit additions. On restricted threads, a team member may add themself;
        adding anyone else requires permission to modify the thread.
        Supply either `user` or `agent` depending on the value of `type`. Targets
        must be visible to the caller and, for an ordinary team-owned thread, must
        belong to the owning team. On success the membership record is returned with
        HTTP 201; repeated agent additions are idempotent.

        Args:
            thread: Thread ID (`thr_...`) identifying the thread to remove the member from.
            input: Request body.
            input.agent: Agent ID of the principal to add. Required when `type` is `"agent"`.
            input.membership_type: Role granted to the new member. One of `"owner"` or `"member"`. Defaults to `"member"`.
            input.type: Kind of principal being added. Must be `"user"` or `"agent"`.
            input.user: User ID of the principal to add. Required when `type` is `"user"`.

        Returns:
            The user or agent membership that was added to the thread.
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/members",
            method="POST",
            body=input,
            response_type=ChatMember,
        )


class AsyncSettingResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def list(self, thread: str) -> SettingListResponse:
        """
        Retrieve thread settings
        Returns the current settings for the specified thread. Settings control
        per-thread behavior such as whether the AI agent is enabled.
        The authenticated user must own the thread or be a member of its workspace.
        If settings have never been explicitly configured, defaults are returned
        (for example, `agent_enabled` defaults to `true`).

        Args:
            thread: Thread ID (`thr_...`). Must belong to the authenticated user's workspace.

        Returns:
            Successful response
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/settings",
            response_type=SettingListResponse,
        )

    async def replace(self, thread: str, input: SettingReplaceInput) -> ThreadSettings:
        """
        Update thread settings
        Updates the settings for the specified thread. Only fields included in
        the `settings` map are modified; omitted fields retain their current values.
        The authenticated user must own the thread or be a member of its workspace.
        Returns the full settings object reflecting the state after the update.
        Validation errors are returned as `422 Unprocessable Entity`.

        Args:
            thread: Thread ID (`thr_...`). Must belong to the authenticated user's workspace.
            input: Request body.
            input.settings: Map of settings fields to update. Include only the keys you want to change.

        Returns:
            The thread settings object after the update has been applied.
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/settings",
            method="PUT",
            body=input,
            response_type=ThreadSettings,
        )


class AsyncTagResource:
    def __init__(self, http: HttpClient):
        self._http = http

    async def remove(self, thread: str) -> Thread:
        """
        Remove tags from a thread
        Removes one or more status tags from the thread and returns the updated
        thread. Removing a tag the thread does not have is a no-op.
        Any participant of the thread a human member or an agent member may edit
        tags. Supply the tags to remove as repeated query parameters, e.g.
        `?tags[]=blocked&tags[]=needs-review`.

        Args:
            thread: Thread ID (`thr_...`) to untag.

        Returns:
            The thread object after the tags were removed.
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/tags",
            method="DELETE",
            response_type=Thread,
        )

    async def create(self, thread: str, input: TagCreateInput) -> Thread:
        """
        Add tags to a thread
        Adds one or more status tags to the thread and returns the updated thread.
        Any participant of the thread a human member or an agent member may edit
        tags; this is broader than the owner/admin permission required to update other
        thread fields. Adding a tag the thread already has is a no-op. Tags are
        normalized (trimmed and lowercased) and may contain only lowercase letters,
        numbers, hyphens, and underscores.

        Args:
            thread: Thread ID (`thr_...`) to untag.
            input: Request body.
            input.tags: Tags to add to the thread.

        Returns:
            The thread object after the tags were added.
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/tags",
            method="POST",
            body=input,
            response_type=Thread,
        )

    async def replace(self, thread: str, input: TagReplaceInput) -> Thread:
        """
        Replace a thread's tags
        Replaces the thread's entire set of status tags with the provided list and
        returns the updated thread. Passing an empty array clears all tags.
        Any participant of the thread a human member or an agent member may edit
        tags. Tags are normalized (trimmed and lowercased) and may contain only
        lowercase letters, numbers, hyphens, and underscores.

        Args:
            thread: Thread ID (`thr_...`) to untag.
            input: Request body.
            input.tags: The complete set of tags for the thread. An empty array clears all tags.

        Returns:
            The thread object after its tags were replaced.
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/tags",
            method="PUT",
            body=input,
            response_type=Thread,
        )


class AsyncThreadResource:
    def __init__(self, http: HttpClient):
        self._http = http
        self.members = AsyncThreadMemberResource(http)
        self.settings = AsyncSettingResource(http)
        self.tags = AsyncTagResource(http)

    async def delete(self, thread: str) -> None:
        """
        Delete a thread
        Permanently deletes a thread and all of its messages and artifacts. This action
        cannot be undone.
        The authenticated user must own the thread or be an owner of the team the thread
        belongs to. Attempting to delete a thread owned by another user or team returns 403.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must own this thread.

        Returns:
            Empty response on successful deletion.
        """
        await self._http.request(f"/api/v1/threads/{thread}", method="DELETE")

    async def get(self, thread: str) -> Thread:
        """
        Retrieve a thread
        Returns the full thread record for the given thread ID. The authenticated user
        must own the thread or be a member of the workspace it belongs to.
        Use this endpoint to fetch the current state of a single thread, including its
        title, description, and metadata. To list many threads, use the list endpoint
        with cursor-based pagination.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have access to this thread.

        Returns:
            The requested thread object.
        """
        return await self._http.request(f"/api/v1/threads/{thread}", response_type=Thread)

    async def replace(self, thread: str, input: ThreadReplaceInput) -> Thread:
        """
        Update a thread
        Updates one or more mutable properties of the specified thread and returns
        the full thread object with the applied changes. Only the fields you provide
        are modified; omitted fields retain their current values.
        If `profile_picture` is supplied, the image is uploaded before the other
        fields are saved, after all ordinary thread fields have passed validation.
        Supplying invalid base64 picture data returns 422 and no other fields are
        updated.
        Visibility can only widen: `private` may become `restricted` or `team`, and
        `restricted` may become `team`. The authenticated viewer must have
        permission to modify the thread.
        Mirror-thread titles, descriptions, and notification state remain editable
        by privileged app viewers. Mirror metadata, visibility, and membership are
        provider-managed and cannot be changed through this endpoint.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have permission to update this thread.
            input: Request body.
            input.description: Optional longer text describing the thread's purpose. Replaces the existing description when provided.
            input.metadata: Arbitrary key-value metadata to store on the thread. Merged with or replaces existing metadata.
            input.muted: When `true`, suppresses notifications for new messages in this thread for the authenticated user.
            input.profile_picture: New profile picture for the thread. Provide all three inner fields to replace the existing image.
            input.title: Human-readable display name for the thread. Replaces the existing title when provided.
            input.visibility: Widen a team-owned thread: `private` may become `restricted` or `team`, and `restricted` may become `team`. Visibility cannot be narrowed.

        Returns:
            The thread object after the update has been applied.
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}",
            method="PUT",
            body=input,
            response_type=Thread,
        )

    async def agents(self, thread: str) -> ThreadAgentsResponse:
        """
        List agents in a thread
        Returns the agents participating in the specified thread. Only personal user
        threads (threads owned by a single user, not a team) expose agents through
        this endpoint; requests for team threads return 404.
        The authenticated user must have visibility into the thread. Each agent entry
        includes display information such as name and profile picture. Thread-level
        overrides (e.g. a custom name or profile picture set for this thread) take
        precedence over the agent's default values. When the caller is the thread
        owner, each entry also includes an `agent_config` object describing the
        agent's message policy and context configuration.

        Args:
            thread: Thread ID (`thr_...`). Must be a personal user thread visible to the authenticated user.

        Returns:
            Successful response
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/agents",
            response_type=ThreadAgentsResponse,
        )

    async def artifacts(self, thread: str) -> ThreadArtifactsResponse:
        """
        List artifacts for a thread
        Returns all artifacts produced during a thread's AI conversation. Artifacts are
        structured outputs such as code files, documents, or generated assets created
        by the AI agent in response to messages in the thread.
        The authenticated user must have access to the specified thread. Results are
        returned in a single page; there is no cursor-based pagination for this endpoint.

        Args:
            thread: Thread ID (`thr_...`). Must be accessible to the authenticated user.

        Returns:
            Successful response
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/artifacts",
            response_type=ThreadArtifactsResponse,
        )

    async def mark_read(self, thread: str, input: ThreadMarkReadInput) -> None:
        """
        Mark a thread as read
        Records that a user has read up to a specific message in the thread. Unread
        indicators and badge counts are cleared up to the specified message.
        You must supply exactly one of `last_read_message` or `use_latest_message`.
        Omitting both returns 400. If `use_latest_message` is `true` and the thread
        has no messages, the request succeeds silently with no state change.
        For server-to-server (S2S) requests where no user identity is present in the
        token, the `user` param is required to identify whose read state to update.

        Args:
            thread: Thread ID (`thr_...`). The thread to mark as read.
            input: Request body.
            input.last_read_message: Message ID (`msg_...`) to record as the last read message. Mutually exclusive with `use_latest_message`.
            input.use_latest_message: When `true`, marks the thread as read up to the latest message. Mutually exclusive with `last_read_message`.
            input.user: User ID (`usr_...`) whose read state to update. Required for S2S requests; ignored when an authenticated user is present in the token.

        Returns:
            Empty response on success.
        """
        await self._http.request(f"/api/v1/threads/{thread}/mark_read", method="POST", body=input)

    async def messages(
        self,
        thread: str,
        *,
        before_cursor: str | None = None,
        after_cursor: str | None = None,
        metadata: dict[str, Any] | None = None,
        limit: int | None = None,
        anchor: str | None = None,
        direction: Literal["before", "after", "around"] | None = None,
        before_limit: int | None = None,
        after_limit: int | None = None,
        include_anchor: bool | None = None,
        anchor_agent_mode: Literal["cli", "embedded"] | None = None,
        anchor_agent: str | None = None,
        include_reply_counts: bool | None = None,
    ) -> ThreadMessagesResponse:
        """
        List messages in a thread
        Returns a cursor-paginated list of messages belonging to the specified thread,
        ordered from oldest to newest. Supply `before_cursor`, `after_cursor`, or both
        to page through or bound the result set; omit both to receive the most recent page.
        Supply `anchor` and `direction` to fetch a window before, after, or around a
        specific message. Use `anchor=last_matching&anchor_agent_mode=embedded` to
        resolve the anchor from the latest embedded-agent message, and add
        `anchor_agent` to scope that resolution to a single sender agent.
        Supply `metadata` as a JSON-encoded structured expression to filter message
        metadata before cursor pagination or anchored window limits are applied.
        The authenticated user must have access to the thread's owner (workspace or user).
        A 403 is returned if the thread exists but is not accessible to the caller; a 404
        is returned if the thread does not exist or is not visible to the authenticated user.
        Pass `include_reply_counts: true` to annotate each message with the number of
        threaded replies it has received. This adds a small amount of latency and should
        be omitted when reply counts are not needed.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have access to this thread.
            before_cursor: Opaque cursor returned in a previous response's `before_cursor` field. When provided, returns messages immediately before that position. May be combined with `after_cursor` to bound a range.
            after_cursor: Opaque cursor returned in a previous response's `after_cursor` field. When provided, returns messages immediately after that position. May be combined with `before_cursor` to bound a range.
            metadata: Structured metadata filter expression. Only messages whose `metadata` object satisfies the expression are returned. The filter is applied before cursor pagination and anchored window limits.
            limit: Maximum number of messages to return per page. Defaults to 20; maximum is 100.
            anchor: Message ID (`msg_...`) to use as a window anchor, or `last_matching` to resolve the anchor from the latest message matching the anchor filters. Cannot be combined with `before_cursor` or `after_cursor`.
            direction: Window direction relative to `anchor`. `before` returns older messages, `after` returns newer messages, and `around` returns messages on both sides. Defaults to `after` when `anchor` is supplied. `direction=around` cannot be combined with an explicit `limit`; use `before_limit` and `after_limit`.
            before_limit: For `direction=around`, maximum number of messages older than the anchor. Defaults to 20; maximum is 100.
            after_limit: For `direction=around`, maximum number of messages newer than the anchor. Defaults to 20; maximum is 100.
            include_anchor: Whether to include the anchor message in a window response. Defaults to `true` for `direction=around`; ignored for ordinary cursor pagination and one-sided windows.
            anchor_agent_mode: When `anchor=last_matching`, resolve the anchor from the latest message with this local agent execution mode.
            anchor_agent: When `anchor=last_matching`, scope the anchor resolution to messages sent by this agent (`agi_...`). Combine with `anchor_agent_mode` to resolve the latest message from a specific agent in a given mode.
            include_reply_counts: When `true`, each message in the response is annotated with its threaded reply count. Defaults to `false`. Adds latency; omit when reply counts are not needed.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if before_cursor is not None:
            query["before_cursor"] = before_cursor
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        if metadata is not None:
            query["metadata"] = metadata
        if limit is not None:
            query["limit"] = limit
        if anchor is not None:
            query["anchor"] = anchor
        if direction is not None:
            query["direction"] = direction
        if before_limit is not None:
            query["before_limit"] = before_limit
        if after_limit is not None:
            query["after_limit"] = after_limit
        if include_anchor is not None:
            query["include_anchor"] = include_anchor
        if anchor_agent_mode is not None:
            query["anchor_agent_mode"] = anchor_agent_mode
        if anchor_agent is not None:
            query["anchor_agent"] = anchor_agent
        if include_reply_counts is not None:
            query["include_reply_counts"] = include_reply_counts
        return await self._http.request(
            f"/api/v1/threads/{thread}/messages",
            query=query,
            response_type=ThreadMessagesResponse,
        )

    async def picture(self, thread: str, input: ThreadPictureInput) -> Thread:
        """
        Update a thread's profile picture
        Uploads a new profile picture for the specified thread and returns the updated
        thread object. The image must be supplied as a base64-encoded string with its
        MIME type.
        The authenticated user must own the thread or be a team owner of the workspace
        the thread belongs to. Supplying invalid base64 data returns 422.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have permission to update this thread.
            input: Request body.
            input.picture: Profile picture payload. Must include the base64-encoded image data and its MIME type.

        Returns:
            The thread object after the profile picture has been updated.
        """
        return await self._http.request(
            f"/api/v1/threads/{thread}/picture",
            method="PUT",
            body=input,
            response_type=Thread,
        )

    async def read_status(self, thread: str, *, user: str | None = None) -> ThreadReadStatus:
        """
        Retrieve a thread's read status
        Returns the read status of a thread for the specified user, including the ID
        of the last message they have read and the number of unread messages remaining.
        For user-authenticated requests, the status is always returned for the
        authenticated user and the `user` parameter is ignored. For server-to-server
        (S2S) requests, the `user` parameter is required and must be a valid user ID.
        Returns 404 if the thread does not exist or the caller does not have access
        to it.

        Args:
            thread: Thread ID (`thr_...`). Must be accessible to the authenticated user or, for S2S requests, to the specified user.
            user: User ID (`usr_...`) whose read status to retrieve. Required for S2S requests; ignored for user-authenticated requests, which always return the status for the authenticated user.

        Returns:
            The read status record for the requested thread and user.
        """
        query: dict[str, object] = {}
        if user is not None:
            query["user"] = user
        return await self._http.request(
            f"/api/v1/threads/{thread}/read_status",
            query=query,
            response_type=ThreadReadStatus,
        )

    async def search(
        self,
        thread: str,
        q: str,
        *,
        app: str | None = None,
        limit: int | None = None,
        mode: Literal["text", "embedding", "hybrid"] | None = None,
        before_cursor: str | None = None,
        after_cursor: str | None = None,
    ) -> ThreadSearchResponse:
        """
        Search messages in a thread
        Searches canonical message content in the specified thread. `"text"` mode
        performs the existing case-insensitive substring search, `"embedding"` ranks
        stored message embeddings by cosine similarity, and `"hybrid"` combines the
        text and embedding rankings with Reciprocal Rank Fusion (RRF). Only messages
        visible to the authenticated caller are considered.
        Results are intentionally lean: each row contains only a bounded content
        snippet, sender identity, and timestamp. Attachments, reactions, ACLs, and
        metadata are neither hydrated nor serialized. At most 20 results are
        returned. Text results support chronological cursor pagination. Embedding and
        hybrid results are relevance-ranked single pages and return null cursors.

        Args:
            thread: Thread ID (`thr_...`). Must be visible to the authenticated caller.
            app: App ID (`app_...`). Required by the protected developer mount and omitted from the public mount.
            q: Text or semantic search query. Must contain 3 to 200 characters after trimming.
            limit: Maximum number of results. Defaults to 20 and is capped at 20.
            mode: Search algorithm: `text` for substring matching, `embedding` for cosine similarity, or `hybrid` for RRF over both rankings.
            before_cursor: Text mode only. Opaque cursor returned by a previous page; fetches older matches.
            after_cursor: Text mode only. Opaque cursor returned by a previous page; fetches newer matches.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if app is not None:
            query["app"] = app
        query["q"] = q
        if limit is not None:
            query["limit"] = limit
        if mode is not None:
            query["mode"] = mode
        if before_cursor is not None:
            query["before_cursor"] = before_cursor
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return await self._http.request(
            f"/api/v1/threads/{thread}/search",
            query=query,
            response_type=ThreadSearchResponse,
        )

    async def trajectories(
        self,
        thread: str,
        *,
        before_cursor: str | None = None,
        after_cursor: str | None = None,
        limit: int | None = None,
        message: str | None = None,
    ) -> ThreadTrajectoriesResponse:
        """
        List trajectories for a thread
        Returns a cursor-paginated list of thread message trajectories associated with the
        specified thread. Each trajectory links a user message and its agent response to the
        underlying AI trajectory record that captured the model's reasoning steps.
        The authenticated user must own the thread or be a member of the workspace it belongs
        to. Results are returned in reverse chronological order by default. Use `before_cursor`
        and `after_cursor` to navigate pages; provide at most one cursor per request.
        Optionally filter results to trajectories produced in response to a specific message
        by supplying the `message` parameter. When no trajectories match the query, `data`
        is an empty array and both cursor fields are `null`. A cursor that cannot be decoded
        returns a 400 `invalid_cursor` error.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must own this thread or belong to its workspace.
            before_cursor: Opaque cursor from a previous response's `before_cursor` field. Returns the page of results preceding that cursor position.
            after_cursor: Opaque cursor from a previous response's `after_cursor` field. Returns the page of results following that cursor position.
            limit: Maximum number of trajectories to return per page. Defaults to 20; maximum is 100.
            message: Message ID (`msg_...`). When provided, limits results to trajectories associated with this specific message.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if before_cursor is not None:
            query["before_cursor"] = before_cursor
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        if limit is not None:
            query["limit"] = limit
        if message is not None:
            query["message"] = message
        return await self._http.request(
            f"/api/v1/threads/{thread}/trajectories",
            query=query,
            response_type=ThreadTrajectoriesResponse,
        )


class ThreadMemberResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def remove(self, thread: str) -> None:
        """
        Remove a member from a thread
        Removes a user or agent from the explicit roster of a private or restricted
        thread. Team-visible threads use implicit membership and reject individual
        removals. A member may remove themself; removing someone else requires
        permission to modify the thread. A successful removal returns HTTP 204 with
        no response body.
        Supply either `user` or `agent` depending on the value of `type`. Returns 404
        if the thread or the membership record does not exist.

        Args:
            thread: Thread ID (`thr_...`) identifying the thread to remove the member from.

        Returns:
            Empty response body. HTTP 204 on success.
        """
        self._http.request(f"/api/v1/threads/{thread}/members", method="DELETE")

    def list(self, thread: str) -> ThreadMemberListResponse:
        """
        List members of a thread
        Returns all current user and agent members. Private and restricted threads
        return their explicit roster; team-visible threads return the owning team's
        implicit roster. The authenticated viewer must be able to see the thread.
        Results are returned as a flat array in the `data` field. The list is not
        paginated all members are returned in a single response.

        Args:
            thread: Thread ID (`thr_...`) identifying the thread to remove the member from.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/members",
            response_type=ThreadMemberListResponse,
        )

    def create(self, thread: str, input: ThreadMemberCreateInput) -> ChatMember:
        """
        Add a member to a thread
        Adds a user or agent to the explicit roster of a private or restricted
        thread. Team-visible threads use the owning team's implicit roster and reject
        explicit additions. On restricted threads, a team member may add themself;
        adding anyone else requires permission to modify the thread.
        Supply either `user` or `agent` depending on the value of `type`. Targets
        must be visible to the caller and, for an ordinary team-owned thread, must
        belong to the owning team. On success the membership record is returned with
        HTTP 201; repeated agent additions are idempotent.

        Args:
            thread: Thread ID (`thr_...`) identifying the thread to remove the member from.
            input: Request body.
            input.agent: Agent ID of the principal to add. Required when `type` is `"agent"`.
            input.membership_type: Role granted to the new member. One of `"owner"` or `"member"`. Defaults to `"member"`.
            input.type: Kind of principal being added. Must be `"user"` or `"agent"`.
            input.user: User ID of the principal to add. Required when `type` is `"user"`.

        Returns:
            The user or agent membership that was added to the thread.
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/members",
            method="POST",
            body=input,
            response_type=ChatMember,
        )


class SettingResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def list(self, thread: str) -> SettingListResponse:
        """
        Retrieve thread settings
        Returns the current settings for the specified thread. Settings control
        per-thread behavior such as whether the AI agent is enabled.
        The authenticated user must own the thread or be a member of its workspace.
        If settings have never been explicitly configured, defaults are returned
        (for example, `agent_enabled` defaults to `true`).

        Args:
            thread: Thread ID (`thr_...`). Must belong to the authenticated user's workspace.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/settings",
            response_type=SettingListResponse,
        )

    def replace(self, thread: str, input: SettingReplaceInput) -> ThreadSettings:
        """
        Update thread settings
        Updates the settings for the specified thread. Only fields included in
        the `settings` map are modified; omitted fields retain their current values.
        The authenticated user must own the thread or be a member of its workspace.
        Returns the full settings object reflecting the state after the update.
        Validation errors are returned as `422 Unprocessable Entity`.

        Args:
            thread: Thread ID (`thr_...`). Must belong to the authenticated user's workspace.
            input: Request body.
            input.settings: Map of settings fields to update. Include only the keys you want to change.

        Returns:
            The thread settings object after the update has been applied.
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/settings",
            method="PUT",
            body=input,
            response_type=ThreadSettings,
        )


class TagResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http

    def remove(self, thread: str) -> Thread:
        """
        Remove tags from a thread
        Removes one or more status tags from the thread and returns the updated
        thread. Removing a tag the thread does not have is a no-op.
        Any participant of the thread a human member or an agent member may edit
        tags. Supply the tags to remove as repeated query parameters, e.g.
        `?tags[]=blocked&tags[]=needs-review`.

        Args:
            thread: Thread ID (`thr_...`) to untag.

        Returns:
            The thread object after the tags were removed.
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/tags",
            method="DELETE",
            response_type=Thread,
        )

    def create(self, thread: str, input: TagCreateInput) -> Thread:
        """
        Add tags to a thread
        Adds one or more status tags to the thread and returns the updated thread.
        Any participant of the thread a human member or an agent member may edit
        tags; this is broader than the owner/admin permission required to update other
        thread fields. Adding a tag the thread already has is a no-op. Tags are
        normalized (trimmed and lowercased) and may contain only lowercase letters,
        numbers, hyphens, and underscores.

        Args:
            thread: Thread ID (`thr_...`) to untag.
            input: Request body.
            input.tags: Tags to add to the thread.

        Returns:
            The thread object after the tags were added.
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/tags",
            method="POST",
            body=input,
            response_type=Thread,
        )

    def replace(self, thread: str, input: TagReplaceInput) -> Thread:
        """
        Replace a thread's tags
        Replaces the thread's entire set of status tags with the provided list and
        returns the updated thread. Passing an empty array clears all tags.
        Any participant of the thread a human member or an agent member may edit
        tags. Tags are normalized (trimmed and lowercased) and may contain only
        lowercase letters, numbers, hyphens, and underscores.

        Args:
            thread: Thread ID (`thr_...`) to untag.
            input: Request body.
            input.tags: The complete set of tags for the thread. An empty array clears all tags.

        Returns:
            The thread object after its tags were replaced.
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/tags",
            method="PUT",
            body=input,
            response_type=Thread,
        )


class ThreadResource:
    def __init__(self, http: SyncHttpClient):
        self._http = http
        self.members = ThreadMemberResource(http)
        self.settings = SettingResource(http)
        self.tags = TagResource(http)

    def delete(self, thread: str) -> None:
        """
        Delete a thread
        Permanently deletes a thread and all of its messages and artifacts. This action
        cannot be undone.
        The authenticated user must own the thread or be an owner of the team the thread
        belongs to. Attempting to delete a thread owned by another user or team returns 403.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must own this thread.

        Returns:
            Empty response on successful deletion.
        """
        self._http.request(f"/api/v1/threads/{thread}", method="DELETE")

    def get(self, thread: str) -> Thread:
        """
        Retrieve a thread
        Returns the full thread record for the given thread ID. The authenticated user
        must own the thread or be a member of the workspace it belongs to.
        Use this endpoint to fetch the current state of a single thread, including its
        title, description, and metadata. To list many threads, use the list endpoint
        with cursor-based pagination.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have access to this thread.

        Returns:
            The requested thread object.
        """
        return self._http.request(f"/api/v1/threads/{thread}", response_type=Thread)

    def replace(self, thread: str, input: ThreadReplaceInput) -> Thread:
        """
        Update a thread
        Updates one or more mutable properties of the specified thread and returns
        the full thread object with the applied changes. Only the fields you provide
        are modified; omitted fields retain their current values.
        If `profile_picture` is supplied, the image is uploaded before the other
        fields are saved, after all ordinary thread fields have passed validation.
        Supplying invalid base64 picture data returns 422 and no other fields are
        updated.
        Visibility can only widen: `private` may become `restricted` or `team`, and
        `restricted` may become `team`. The authenticated viewer must have
        permission to modify the thread.
        Mirror-thread titles, descriptions, and notification state remain editable
        by privileged app viewers. Mirror metadata, visibility, and membership are
        provider-managed and cannot be changed through this endpoint.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have permission to update this thread.
            input: Request body.
            input.description: Optional longer text describing the thread's purpose. Replaces the existing description when provided.
            input.metadata: Arbitrary key-value metadata to store on the thread. Merged with or replaces existing metadata.
            input.muted: When `true`, suppresses notifications for new messages in this thread for the authenticated user.
            input.profile_picture: New profile picture for the thread. Provide all three inner fields to replace the existing image.
            input.title: Human-readable display name for the thread. Replaces the existing title when provided.
            input.visibility: Widen a team-owned thread: `private` may become `restricted` or `team`, and `restricted` may become `team`. Visibility cannot be narrowed.

        Returns:
            The thread object after the update has been applied.
        """
        return self._http.request(
            f"/api/v1/threads/{thread}",
            method="PUT",
            body=input,
            response_type=Thread,
        )

    def agents(self, thread: str) -> ThreadAgentsResponse:
        """
        List agents in a thread
        Returns the agents participating in the specified thread. Only personal user
        threads (threads owned by a single user, not a team) expose agents through
        this endpoint; requests for team threads return 404.
        The authenticated user must have visibility into the thread. Each agent entry
        includes display information such as name and profile picture. Thread-level
        overrides (e.g. a custom name or profile picture set for this thread) take
        precedence over the agent's default values. When the caller is the thread
        owner, each entry also includes an `agent_config` object describing the
        agent's message policy and context configuration.

        Args:
            thread: Thread ID (`thr_...`). Must be a personal user thread visible to the authenticated user.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/agents",
            response_type=ThreadAgentsResponse,
        )

    def artifacts(self, thread: str) -> ThreadArtifactsResponse:
        """
        List artifacts for a thread
        Returns all artifacts produced during a thread's AI conversation. Artifacts are
        structured outputs such as code files, documents, or generated assets created
        by the AI agent in response to messages in the thread.
        The authenticated user must have access to the specified thread. Results are
        returned in a single page; there is no cursor-based pagination for this endpoint.

        Args:
            thread: Thread ID (`thr_...`). Must be accessible to the authenticated user.

        Returns:
            Successful response
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/artifacts",
            response_type=ThreadArtifactsResponse,
        )

    def mark_read(self, thread: str, input: ThreadMarkReadInput) -> None:
        """
        Mark a thread as read
        Records that a user has read up to a specific message in the thread. Unread
        indicators and badge counts are cleared up to the specified message.
        You must supply exactly one of `last_read_message` or `use_latest_message`.
        Omitting both returns 400. If `use_latest_message` is `true` and the thread
        has no messages, the request succeeds silently with no state change.
        For server-to-server (S2S) requests where no user identity is present in the
        token, the `user` param is required to identify whose read state to update.

        Args:
            thread: Thread ID (`thr_...`). The thread to mark as read.
            input: Request body.
            input.last_read_message: Message ID (`msg_...`) to record as the last read message. Mutually exclusive with `use_latest_message`.
            input.use_latest_message: When `true`, marks the thread as read up to the latest message. Mutually exclusive with `last_read_message`.
            input.user: User ID (`usr_...`) whose read state to update. Required for S2S requests; ignored when an authenticated user is present in the token.

        Returns:
            Empty response on success.
        """
        self._http.request(f"/api/v1/threads/{thread}/mark_read", method="POST", body=input)

    def messages(
        self,
        thread: str,
        *,
        before_cursor: str | None = None,
        after_cursor: str | None = None,
        metadata: dict[str, Any] | None = None,
        limit: int | None = None,
        anchor: str | None = None,
        direction: Literal["before", "after", "around"] | None = None,
        before_limit: int | None = None,
        after_limit: int | None = None,
        include_anchor: bool | None = None,
        anchor_agent_mode: Literal["cli", "embedded"] | None = None,
        anchor_agent: str | None = None,
        include_reply_counts: bool | None = None,
    ) -> ThreadMessagesResponse:
        """
        List messages in a thread
        Returns a cursor-paginated list of messages belonging to the specified thread,
        ordered from oldest to newest. Supply `before_cursor`, `after_cursor`, or both
        to page through or bound the result set; omit both to receive the most recent page.
        Supply `anchor` and `direction` to fetch a window before, after, or around a
        specific message. Use `anchor=last_matching&anchor_agent_mode=embedded` to
        resolve the anchor from the latest embedded-agent message, and add
        `anchor_agent` to scope that resolution to a single sender agent.
        Supply `metadata` as a JSON-encoded structured expression to filter message
        metadata before cursor pagination or anchored window limits are applied.
        The authenticated user must have access to the thread's owner (workspace or user).
        A 403 is returned if the thread exists but is not accessible to the caller; a 404
        is returned if the thread does not exist or is not visible to the authenticated user.
        Pass `include_reply_counts: true` to annotate each message with the number of
        threaded replies it has received. This adds a small amount of latency and should
        be omitted when reply counts are not needed.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have access to this thread.
            before_cursor: Opaque cursor returned in a previous response's `before_cursor` field. When provided, returns messages immediately before that position. May be combined with `after_cursor` to bound a range.
            after_cursor: Opaque cursor returned in a previous response's `after_cursor` field. When provided, returns messages immediately after that position. May be combined with `before_cursor` to bound a range.
            metadata: Structured metadata filter expression. Only messages whose `metadata` object satisfies the expression are returned. The filter is applied before cursor pagination and anchored window limits.
            limit: Maximum number of messages to return per page. Defaults to 20; maximum is 100.
            anchor: Message ID (`msg_...`) to use as a window anchor, or `last_matching` to resolve the anchor from the latest message matching the anchor filters. Cannot be combined with `before_cursor` or `after_cursor`.
            direction: Window direction relative to `anchor`. `before` returns older messages, `after` returns newer messages, and `around` returns messages on both sides. Defaults to `after` when `anchor` is supplied. `direction=around` cannot be combined with an explicit `limit`; use `before_limit` and `after_limit`.
            before_limit: For `direction=around`, maximum number of messages older than the anchor. Defaults to 20; maximum is 100.
            after_limit: For `direction=around`, maximum number of messages newer than the anchor. Defaults to 20; maximum is 100.
            include_anchor: Whether to include the anchor message in a window response. Defaults to `true` for `direction=around`; ignored for ordinary cursor pagination and one-sided windows.
            anchor_agent_mode: When `anchor=last_matching`, resolve the anchor from the latest message with this local agent execution mode.
            anchor_agent: When `anchor=last_matching`, scope the anchor resolution to messages sent by this agent (`agi_...`). Combine with `anchor_agent_mode` to resolve the latest message from a specific agent in a given mode.
            include_reply_counts: When `true`, each message in the response is annotated with its threaded reply count. Defaults to `false`. Adds latency; omit when reply counts are not needed.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if before_cursor is not None:
            query["before_cursor"] = before_cursor
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        if metadata is not None:
            query["metadata"] = metadata
        if limit is not None:
            query["limit"] = limit
        if anchor is not None:
            query["anchor"] = anchor
        if direction is not None:
            query["direction"] = direction
        if before_limit is not None:
            query["before_limit"] = before_limit
        if after_limit is not None:
            query["after_limit"] = after_limit
        if include_anchor is not None:
            query["include_anchor"] = include_anchor
        if anchor_agent_mode is not None:
            query["anchor_agent_mode"] = anchor_agent_mode
        if anchor_agent is not None:
            query["anchor_agent"] = anchor_agent
        if include_reply_counts is not None:
            query["include_reply_counts"] = include_reply_counts
        return self._http.request(
            f"/api/v1/threads/{thread}/messages",
            query=query,
            response_type=ThreadMessagesResponse,
        )

    def picture(self, thread: str, input: ThreadPictureInput) -> Thread:
        """
        Update a thread's profile picture
        Uploads a new profile picture for the specified thread and returns the updated
        thread object. The image must be supplied as a base64-encoded string with its
        MIME type.
        The authenticated user must own the thread or be a team owner of the workspace
        the thread belongs to. Supplying invalid base64 data returns 422.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must have permission to update this thread.
            input: Request body.
            input.picture: Profile picture payload. Must include the base64-encoded image data and its MIME type.

        Returns:
            The thread object after the profile picture has been updated.
        """
        return self._http.request(
            f"/api/v1/threads/{thread}/picture",
            method="PUT",
            body=input,
            response_type=Thread,
        )

    def read_status(self, thread: str, *, user: str | None = None) -> ThreadReadStatus:
        """
        Retrieve a thread's read status
        Returns the read status of a thread for the specified user, including the ID
        of the last message they have read and the number of unread messages remaining.
        For user-authenticated requests, the status is always returned for the
        authenticated user and the `user` parameter is ignored. For server-to-server
        (S2S) requests, the `user` parameter is required and must be a valid user ID.
        Returns 404 if the thread does not exist or the caller does not have access
        to it.

        Args:
            thread: Thread ID (`thr_...`). Must be accessible to the authenticated user or, for S2S requests, to the specified user.
            user: User ID (`usr_...`) whose read status to retrieve. Required for S2S requests; ignored for user-authenticated requests, which always return the status for the authenticated user.

        Returns:
            The read status record for the requested thread and user.
        """
        query: dict[str, object] = {}
        if user is not None:
            query["user"] = user
        return self._http.request(
            f"/api/v1/threads/{thread}/read_status",
            query=query,
            response_type=ThreadReadStatus,
        )

    def search(
        self,
        thread: str,
        q: str,
        *,
        app: str | None = None,
        limit: int | None = None,
        mode: Literal["text", "embedding", "hybrid"] | None = None,
        before_cursor: str | None = None,
        after_cursor: str | None = None,
    ) -> ThreadSearchResponse:
        """
        Search messages in a thread
        Searches canonical message content in the specified thread. `"text"` mode
        performs the existing case-insensitive substring search, `"embedding"` ranks
        stored message embeddings by cosine similarity, and `"hybrid"` combines the
        text and embedding rankings with Reciprocal Rank Fusion (RRF). Only messages
        visible to the authenticated caller are considered.
        Results are intentionally lean: each row contains only a bounded content
        snippet, sender identity, and timestamp. Attachments, reactions, ACLs, and
        metadata are neither hydrated nor serialized. At most 20 results are
        returned. Text results support chronological cursor pagination. Embedding and
        hybrid results are relevance-ranked single pages and return null cursors.

        Args:
            thread: Thread ID (`thr_...`). Must be visible to the authenticated caller.
            app: App ID (`app_...`). Required by the protected developer mount and omitted from the public mount.
            q: Text or semantic search query. Must contain 3 to 200 characters after trimming.
            limit: Maximum number of results. Defaults to 20 and is capped at 20.
            mode: Search algorithm: `text` for substring matching, `embedding` for cosine similarity, or `hybrid` for RRF over both rankings.
            before_cursor: Text mode only. Opaque cursor returned by a previous page; fetches older matches.
            after_cursor: Text mode only. Opaque cursor returned by a previous page; fetches newer matches.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if app is not None:
            query["app"] = app
        query["q"] = q
        if limit is not None:
            query["limit"] = limit
        if mode is not None:
            query["mode"] = mode
        if before_cursor is not None:
            query["before_cursor"] = before_cursor
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        return self._http.request(
            f"/api/v1/threads/{thread}/search",
            query=query,
            response_type=ThreadSearchResponse,
        )

    def trajectories(
        self,
        thread: str,
        *,
        before_cursor: str | None = None,
        after_cursor: str | None = None,
        limit: int | None = None,
        message: str | None = None,
    ) -> ThreadTrajectoriesResponse:
        """
        List trajectories for a thread
        Returns a cursor-paginated list of thread message trajectories associated with the
        specified thread. Each trajectory links a user message and its agent response to the
        underlying AI trajectory record that captured the model's reasoning steps.
        The authenticated user must own the thread or be a member of the workspace it belongs
        to. Results are returned in reverse chronological order by default. Use `before_cursor`
        and `after_cursor` to navigate pages; provide at most one cursor per request.
        Optionally filter results to trajectories produced in response to a specific message
        by supplying the `message` parameter. When no trajectories match the query, `data`
        is an empty array and both cursor fields are `null`. A cursor that cannot be decoded
        returns a 400 `invalid_cursor` error.

        Args:
            thread: Thread ID (`thr_...`). The authenticated user must own this thread or belong to its workspace.
            before_cursor: Opaque cursor from a previous response's `before_cursor` field. Returns the page of results preceding that cursor position.
            after_cursor: Opaque cursor from a previous response's `after_cursor` field. Returns the page of results following that cursor position.
            limit: Maximum number of trajectories to return per page. Defaults to 20; maximum is 100.
            message: Message ID (`msg_...`). When provided, limits results to trajectories associated with this specific message.

        Returns:
            Successful response
        """
        query: dict[str, object] = {}
        if before_cursor is not None:
            query["before_cursor"] = before_cursor
        if after_cursor is not None:
            query["after_cursor"] = after_cursor
        if limit is not None:
            query["limit"] = limit
        if message is not None:
            query["message"] = message
        return self._http.request(
            f"/api/v1/threads/{thread}/trajectories",
            query=query,
            response_type=ThreadTrajectoriesResponse,
        )
